from itertools import combinations

g = combinations(range(22), 2)
edge_list = list(g)

# Initialize the coloring
coloring = [0] * len(edge_list)

# Function to check if a clique is monochromatic
def is_monochromatic(clique, color):
    for i in range(len(clique)):
        for j in range(i+1, len(clique)):
            edge = (clique[i], clique[j])
            if edge not in edge_list and (clique[j], clique[i]) not in edge_list:
                continue
            idx = edge_list.index(edge) if edge in edge_list else edge_list.index((clique[j], clique[i]))
            if coloring[idx] != color:
                return False
    return True

# Function to check if the coloring is valid
def is_valid(coloring):
    # Check for monochromatic red cliques of size 4
    for clique in combinations(range(22), 4):
        if is_monochromatic(clique, 0):
            return False
    # Check for monochromatic blue cliques of size 5
    for clique in combinations(range(22), 5):
        if is_monochromatic(clique, 1):
            return False
    return True

# Perform a random search for a valid coloring
import random
while True:
    random_coloring = [random.randint(0, 1) for _ in range(len(edge_list))]
    if is_valid(random_coloring):
        print(random_coloring)
        break
